const $=s=>document.querySelector(s), key='misty-ferry-v1';
const clues=[
{id:'rope',name:'渡船封绳',type:'物证 · 青石渡口',icon:'绳',text:'亥初封渡时，巡丁在船绳上贴了红纸封条。如今封条完整，绳结未动。船从封渡之后便没有离岸。',x:70,y:72},
{id:'boatman',name:'船夫的证言',type:'证言 · 青石渡口',icon:'言',text:'“亥初封渡，巡丁收了我的桨，我一直守在船边。亥正，我看见陆掌柜从库房出来，拎着蓝布包。那会儿雨正大。”',x:29,y:70},
{id:'ledger',name:'交接簿',type:'物证 · 渡口库房',icon:'簿',text:'簿上记着：亥初，差役验印入匣，库门落锁；唯一钥匙交给陆掌柜。船夫自亥初起未再入库。亥末复验时，官印失踪，门锁完好。',x:38,y:63},
{id:'wax',name:'蓝布与朱蜡',type:'物证 · 渡口库房',icon:'蜡',text:'柜门内的铁钩上挂着一缕蓝布纤维，沾有刚剥落的朱红封蜡。印匣封口也残留同色蜡屑，说明有人在这里打开了印匣。',x:72,y:43},
{id:'keeper',name:'掌柜的证言',type:'证言 · 听雨茶棚',icon:'言',text:'“亥初领了库房钥匙，我就没离开茶棚。亥正，我亲眼看见船夫划船离岸。至于蓝布包？不过是我的旧衣。”',x:42,y:61},
{id:'bundle',name:'藏印的蓝布包',type:'物证 · 听雨茶棚',icon:'印',text:'掌柜座椅下的蓝布包破了一角，断口正能与铁钩上的布丝对合。包内藏着失窃的官印，印底编号与交接簿一致；内衬还有朱蜡碎屑。',x:76,y:77}
];
const places=[{name:'青石渡口',sub:'亥时 · 雨未歇',poem:'江上烟波起 · 渡头人未归',ids:['rope','boatman']},{name:'渡口库房',sub:'亥末 · 封匣已空',poem:'一匣空余锁 · 半缕藏真言',ids:['ledger','wax']},{name:'听雨茶棚',sub:'子初 · 灯下问心',poem:'灯火知长夜 · 人言隔重山',ids:['keeper','bundle']}];
let state={found:[],place:0,solved:false},tab='evidence',hintCount=0;
try{const s=JSON.parse(localStorage.getItem(key));if(s&&Array.isArray(s.found)){state={found:[...new Set(s.found.filter(id=>clues.some(c=>c.id===id)))],place:[0,1,2].includes(s.place)?s.place:0,solved:s.solved===true&&s.found.length===6}}}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{$('#save-note').textContent='浏览器无法存档，请在本页继续游玩'}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function show(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}$('.close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});
function svgScene(n){const defs=`<defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#75938d"/><stop offset="1" stop-color="#bcc4ad"/></linearGradient><linearGradient id="water" x2="0" y2="1"><stop stop-color="#547b79"/><stop offset="1" stop-color="#203e45"/></linearGradient><radialGradient id="glow"><stop stop-color="#f1c77e" stop-opacity=".6"/><stop offset="1" stop-color="#d7aa5a" stop-opacity="0"/></radialGradient><filter id="paper"><feTurbulence type="fractalNoise" baseFrequency=".45" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".10"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs>`;
const roof=(x,y,w)=>`<path d="M${x-35} ${y+42} Q${x+15} ${y+20} ${x+35} ${y-10} L${x+w-35} ${y-10} Q${x+w-15} ${y+20} ${x+w+35} ${y+42} Z" fill="#203b3e" stroke="#526a62" stroke-width="4"/><path d="M${x-23} ${y+37}H${x+w+23}" stroke="#879086" stroke-width="2"/>`;
const lantern=(x,y)=>`<path d="M${x} ${y-38}v40" stroke="#2b3631" stroke-width="3"/><circle cx="${x}" cy="${y+18}" r="85" fill="url(#glow)"/><rect x="${x-13}" y="${y}" width="26" height="36" rx="7" fill="#d8b271"/><path d="M${x-12} ${y+5}h24m-24 25h24m-12-25v25m0 6v12" stroke="#82603f" stroke-width="2"/>`;
const person=(x,y,c)=>`<ellipse cx="${x}" cy="${y+74}" rx="28" ry="6" fill="#162f3488"/><path d="M${x-10} ${y+17}q10-12 20 0l12 51-19 6-8-4-18-3z" fill="${c}"/><circle cx="${x}" cy="${y+2}" r="10" fill="#b0a58b"/><path d="M${x-12} ${y}q12-22 24 0z" fill="#283b36"/>`;
let bg=`<rect width="1000" height="570" fill="url(#sky)"/><path d="M0 215Q90 40 210 170T410 145T650 160T880 100T1100 180V400H0" fill="#77948a"/><path d="M0 250Q120 160 250 238T490 210T710 240T1000 180V400H0" fill="#62857f"/><path d="M0 295Q150 210 330 285T620 260T1000 250V440H0" fill="#527772"/><rect y="320" width="1000" height="250" fill="url(#water)"/>`;
for(let i=0;i<35;i++){let x=(i*137)%1000,y=330+(i*23)%230;bg+=`<path d="M${x} ${y}h${20+i%7*12}" stroke="#96b0a1" opacity=".18"/>`}
if(n===0){bg+=`<path d="M0 405L575 440 1000 520V570H0" fill="#4d605b"/><path d="M0 445L530 464 820 570H0" fill="#69766a"/><path d="M20 470l610 30M0 515l720 34M170 447l-55 123m210-113-30 113m155-98 55 98" stroke="#394e4c" stroke-width="3" opacity=".8"/><path d="M625 430q110 47 270-9l-27 40q-150 25-213-7z" fill="#273e3d"/><path d="M675 428q65-110 155 0z" fill="#687466" stroke="#263f3e" stroke-width="5"/><path d="M700 428q40-85 100 0m-80 0q25-80 60 0" fill="none" stroke="#a0a58b" stroke-width="2"/><path d="M600 440h40m-20-45v90m0-57 70 14" stroke="#302f29" stroke-width="7"/><rect x="632" y="431" width="10" height="7" fill="#b46d54"/><rect x="110" y="238" width="220" height="186" fill="#556b60"/><rect x="137" y="289" width="158" height="130" fill="#304a43"/><path d="M110 256v181m220-181v199" stroke="#2d423b" stroke-width="14"/>${roof(92,212,255)}${lantern(307,283)}${person(290,369,'#6a7460')}<path d="M928 0q-55 105-28 300l-18 133h37l-5-123q-28-140 45-310" fill="#2c4945"/><path d="M915 90Q810 33 700 65m215 54Q800 64 730 170m192-15Q970 73 1020 105" fill="none" stroke="#314f47" stroke-width="13"/>`;for(let i=0;i<20;i++)bg+=`<path d="M${700+i*14} ${60+(i%5)*15}q-15 80-5 ${110+i%6*14}" fill="none" stroke="#395d50" stroke-width="3" opacity=".8"/>`}
if(n===1){bg+=`<rect x="60" y="40" width="890" height="490" fill="#334b44"/><rect x="100" y="90" width="800" height="360" fill="#4d5e50"/><path d="M60 470h890l50 100H0z" fill="#617165"/><path d="M80 70v470m260-470v440m580-440v470M60 70h890M50 455h900" stroke="#293e36" stroke-width="22"/><rect x="120" y="125" width="170" height="190" fill="#9cae92"/><path d="M145 125v190m40-190v190m40-190v190m40-190v190m-145-150h170m-170 45h170m-170 45h170" stroke="#354d42" stroke-width="8"/><rect x="625" y="195" width="180" height="240" fill="#293f35" stroke="#8a8d68" stroke-width="4"/><path d="M715 200v230" stroke="#6b7756" stroke-width="4"/><rect x="653" y="295" width="112" height="55" fill="#6c5b3f" stroke="#b2a177" stroke-width="3"/><path d="M650 310h118" stroke="#bdac79"/><circle cx="710" cy="319" r="5" fill="#a14e39"/><path d="M756 220v25l-12 6" fill="none" stroke="#839582" stroke-width="4"/><path d="M747 246l-5 25" stroke="#5c8492" stroke-width="5"/><path d="M247 383h280v25H247zm18 25h17v110h-17m216-110h17v110h-17" fill="#2c4034"/><path d="M320 366l75-7 37 23-83 6z" fill="#c4bc96"/><path d="M338 368l50-4m-39 11 49-4" stroke="#62705a" stroke-width="2"/>${lantern(540,130)}<rect x="120" y="365" width="85" height="85" fill="#7a7854" stroke="#354e3c" stroke-width="5"/>`}
if(n===2){bg+=`<path d="M80 400H970v170H0z" fill="#5b6f61"/><rect x="160" y="210" width="720" height="190" fill="#465e50"/>${roof(120,145,790)}<path d="M130 188v350m750-350v350M510 188v340" stroke="#2c443b" stroke-width="17"/><path d="M120 236h765" stroke="#9b9975" stroke-width="5"/><path d="M230 340h330v25H230m30 0v130m270-130v130" stroke="#303f31" fill="#786f4d" stroke-width="10"/><path d="M340 326h35v15h-35m30-15q25 8 0 13" fill="#b6b395"/><path d="M650 374h170v15H650m14 15v110m143-110v110" stroke="#303f31" fill="#655d40" stroke-width="9"/><path d="M708 446q40-50 75 0l16 25q-52 27-101 0z" fill="#426d79"/><path d="M739 424l16 52m-41-32 69 22" stroke="#789198" stroke-width="3"/>${person(425,300,'#87775b')}${lantern(620,220)}${lantern(240,210)}<rect x="788" y="230" width="45" height="100" fill="#b9b28a"/><text x="810" y="265" fill="#455440" font-size="25" text-anchor="middle">茶</text><path d="M0 550l1000-13" stroke="#293f38" stroke-width="8"/>`}
return `<svg viewBox="0 0 1000 570" preserveAspectRatio="xMidYMid slice" aria-label="${places[n].name}水墨场景" role="img">${defs}<g filter="url(#paper)">${bg}<rect width="1000" height="570" fill="#183d40" opacity=".12"/></g></svg>`}
function render(){const p=places[state.place];$('#place').textContent=p.name;$('#time').textContent=p.sub;$('#caption').textContent=p.poem;$('#art').innerHTML=svgScene(state.place);$('#progress').textContent=`线索 ${state.found.length} / 6`;$('#phase').textContent=state.solved?'已结案':'调查阶段';$('.stamp').textContent=state.solved?'已结':'待解';$('#goal').textContent=state.solved?'真相已明。可以回看证据或重新开始。':state.found.length===6?'证据齐备，梳理谎言、手法与藏匿处。':'勘察三个地点，收集物证与证言。';$('#deduce').innerHTML=state.solved?'重温真相 <span>→</span>':'梳理案情 <span>→</span>';$('#locations').innerHTML=places.map((p,i)=>`<button class="${i===state.place?'active':''}" data-place="${i}" aria-current="${i===state.place?'location':'false'}">0${i+1} · ${p.name}</button>`).join('');$('#spots').innerHTML=p.ids.map(id=>{const c=clues.find(c=>c.id===id);return `<button class="spot ${state.found.includes(id)?'found':''}" style="left:${c.x}%;top:${c.y}%" data-clue="${id}"><i></i><span>${state.found.includes(id)?'✓ ':''}${c.name}</span></button>`}).join('');renderBook()}
function renderBook(){$('#notebook').innerHTML=tab==='story'?`<div class="story">光绪末年，江南青石渡。<br><br>亥初，运送官印的差役验印封匣，交由陆掌柜暂存。大雨封渡，众人留宿。<br><br>亥末，库门未损，官印却不翼而飞。掌柜指认船夫乘船盗印。你是恰好留宿的书生沈砚，要在天亮前查清此事。<br><br>记时：亥初 → 亥正 → 亥末。</div>`:state.found.length?state.found.map(id=>{const c=clues.find(c=>c.id===id);return `<button class="evidence" data-review="${id}"><em>${c.icon}</em><div><b>${c.name}</b><small>${c.type}</small></div></button>`}).join(''):`<div class="empty"><b>◇</b>雨会抹去足迹，<br>却抹不去事情发生的次序。<br><br>点击场景光点，收录第一条线索。</div>`}
function inspect(id){const c=clues.find(c=>c.id===id);const isNew=!state.found.includes(id);if(isNew){state.found.push(id);save();render();toast(`已收录：${c.name}`)}$('#character').style.left=`${Math.max(10,Math.min(85,c.x-8))}%`;$('#speaker').textContent=c.type.startsWith('证言')?c.name:'沈砚 · 勘察笔记';$('#dialogue').textContent=c.text;show(`<span class="tag">${c.type} / ${isNew?'新线索':'案卷回看'}</span><h2>${c.name}</h2><p>${c.text}</p><button class="primary" id="continue">记入案卷，继续调查 <span>→</span></button>`);$('#continue').onclick=close}
document.addEventListener('click',e=>{const p=e.target.closest('[data-place]');if(p){state.place=Number(p.dataset.place);save();render();$('#dialogue').textContent=`来到${places[state.place].name}。仔细看看这里的人与物，线索常藏在细节里。`;$('#speaker').textContent='沈砚 · 游历书生'}const c=e.target.closest('[data-clue]');if(c)inspect(c.dataset.clue);const r=e.target.closest('[data-review]');if(r)inspect(r.dataset.review);const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===t));renderBook()}});
$('#hint').onclick=()=>{hintCount++;const missing=clues.find(c=>!state.found.includes(c.id));if(missing){const p=places.find(p=>p.ids.includes(missing.id));toast(`寻迹：去「${p.name}」查看「${missing.name}」。`)}else{toast(['想一想：封条完好的船，真的离岸了吗？','钥匙由谁保管？交接簿限定了作案时段。','蓝布断口与朱蜡，把库房和藏印处连在了一起。'][(hintCount-1)%3])}};
const questions=[{q:'一、哪条证据直接推翻“船夫亥正划船离岸”？',options:['船夫的证言','渡船封绳','交接簿'],a:'渡船封绳',why:'封绳完整说明船没有离岸；单凭船夫自述还不能直接证伪。'},{q:'二、验印之后，谁持有库房唯一钥匙？',options:['船夫','差役','陆掌柜'],a:'陆掌柜',why:'交接簿记载亥初验印后，唯一钥匙交给陆掌柜，门锁又没有损坏。'},{q:'三、什么把蓝布包与开匣现场联系起来？',options:['布包颜色鲜艳','断口相合的蓝布与朱蜡','茶棚离库房很近'],a:'断口相合的蓝布与朱蜡',why:'仅凭颜色或距离不足以定论；吻合的断口与同色封蜡组成物证联系。'}];
function ending(){show(`<span class="tag">第一回 · 真相大白</span><h2>雨停之前，真相已明。</h2><p>陆掌柜在亥初验印之后，利用唯一钥匙进入库房，打开印匣，将官印藏进自己的蓝布包。离开时，布包被柜内铁钩扯破，留下沾蜡的布丝。</p><p>他回到茶棚，将布包藏在座椅下，再捏造船夫划船离岸的说法。但完好的封绳推翻了他的指认，交接簿限定了作案机会，而断口和封蜡将布包与现场相连。失印最终从包内起获。</p><p>船夫的证言得到了物证印证。至于掌柜为何盗印，尚需交由衙门继续追查。</p><p class="tag">案件完成 · 六条线索 / 三步推理</p><button class="primary" id="finish">合上案卷 <span>✓</span></button>`);$('#finish').onclick=close}
$('#deduce').onclick=()=>{if(state.solved)return ending();if(state.found.length<6){show(`<span class="tag">案情尚未明朗</span><h2>还缺 ${6-state.found.length} 条线索</h2><p>走访渡口、库房与茶棚。物证和证言都收录后，才能把案情连成完整的证据链。</p><button class="primary" id="back">继续调查 <span>→</span></button>`);$('#back').onclick=close;return}show(`<span class="tag">推理 · 用证据还原经过</span><h2>谁在雨夜说了谎？</h2><form id="deduction">${questions.map((q,i)=>`<label class="question" for="q${i}">${q.q}</label><select id="q${i}" required><option value="">选择判断依据</option>${q.options.map(o=>`<option>${o}</option>`).join('')}</select>`).join('')}<div class="feedback" id="feedback" role="status"></div><button class="primary" type="submit">提交推理 <span>→</span></button></form>`);$('#deduction').onsubmit=e=>{e.preventDefault();const wrong=questions.findIndex((q,i)=>$('#q'+i).value!==q.a);if(wrong>=0){$('#feedback').textContent=`第 ${wrong+1} 步需要再想一想。${questions[wrong].why}`;$('#q'+wrong).focus()}else{state.solved=true;save();render();ending()}}};
$('#restart').onclick=()=>{show('<span class="tag">重新调查</span><h2>从雨夜渡口重新开始？</h2><p>这会清除本浏览器中当前案件的调查进度。</p><button class="primary" id="reset">确认重新开始</button>');$('#reset').onclick=()=>{state={found:[],place:0,solved:false};hintCount=0;save();render();close();$('#speaker').textContent='沈砚 · 游历书生';$('#dialogue').textContent='官印在封渡后失窃，船夫却被指为窃贼。先看看这雨夜，留下了什么。'}};
let audioCtx,source,gain,sound=false;$('#sound').onclick=async()=>{try{if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.25;source=audioCtx.createBufferSource();source.buffer=buffer;source.loop=true;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1200;gain=audioCtx.createGain();gain.gain.value=0;source.connect(filter).connect(gain).connect(audioCtx.destination);source.start()}await audioCtx.resume();sound=!sound;gain.gain.setTargetAtTime(sound?.22:0,audioCtx.currentTime,.3);$('#sound').textContent=`◌ 雨声：${sound?'开':'关'}`;$('#sound').setAttribute('aria-pressed',String(sound))}catch{toast('当前浏览器不支持环境音效。')}};
render();
